'use strict';
const root=document.getElementById('main');const home=root.innerHTML;
document.getElementById('home-nav').classList.add('active');
let spaces=[];let loading;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function inline(s){return esc(s).replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>').replace(/`([^`]+)`/g,'<code>$1</code>').replace(/\[([^\]]+)\]\(#question-(\d+)\)/g,(_,label,n)=>`<a href="#/interview/general/general-question-${n.padStart(2,'0')}">${label}</a>`);}
function markdown(value){const blocks=String(value||'').trim().split(/\n\s*\n/);return blocks.map(b=>{if(/^\|/.test(b)){const lines=b.split('\n').filter(l=>!/^\|\s*:?-+/.test(l));return `<table>${lines.map((l,i)=>'<tr>'+l.trim().replace(/^\||\|$/g,'').split('|').map(cell=>`<${i?'td':'th'}>${inline(cell.trim())}</${i?'td':'th'}>`).join('')+'</tr>').join('')}</table>`;}if(/^#{1,6} /.test(b)){return b.split('\n').map(l=>/^#{1,6} /.test(l)?`<h3>${inline(l.replace(/^#+ /,''))}</h3>`:`<p>${inline(l)}</p>`).join('');}return `<p>${inline(b)}</p>`;}).join('');}
const link=(s,q)=>`#/interview/${s.id}${q?'/'+q.id:''}`;
function crumbs(s,q){return `<div class="crumb"><a href="#/">首页</a><span>/</span><a href="#/interview">面试项</a>${s?`<span>/</span><a href="${link(s)}">${esc(s.name)}</a>`:''}${q?'<span>/</span><span>逐题阅读</span>':''}</div>`;}
function notFound(){root.innerHTML='<div class="empty"><h1>这篇笔记还不存在</h1><a class="button" href="#/interview">返回面试项</a></div>';}

function reviewIndex(s){if(!s.recap_count)return '';const groups=new Map();for(const q of s.questions)for(const r of q.reviews||[]){if(!groups.has(r.source))groups.set(r.source,[]);groups.get(r.source).push({q,r});}return `<section class="recap-index"><h2>面试复盘</h2><p>四份复盘共 31 条：25 条归入已有题目，6 条补充为新题。展开题目的参考回答，可查看回答欠佳点与表格参考稿。</p>${[...groups].sort(([a],[b])=>a.localeCompare(b,'zh-CN',{numeric:true})).map(([name,items])=>`<details><summary>${esc(name.replace('.xlsx',''))} <small>${items.length} 条</small></summary>${items.sort((a,b)=>a.r.row-b.r.row).map(({q,r})=>`<a href="${link(s,q)}"><span>${esc(r.question)}</span><small>题目 ${q.number}${q.answer_origin==='recap'?' · 新增':''}</small></a>`).join('')}</details>`).join('')}</section>`;}
function reviewPanels(q){if(!q.reviews?.length)return '';return `<section class="review-panels"><h2>面试复盘（${q.reviews.length} 条）</h2>${q.reviews.map(r=>`<div class="review-entry"><p class="review-source">${esc(r.source)} · ${esc(r.sheet)} · 第 ${r.row} 行</p><h3>原始问法</h3><p>${esc(r.question)}</p><div class="review-feedback"><h3>${esc(r.feedback_label)}</h3><p>${esc(r.feedback)}</p></div>${r.note?`<div class="review-note"><h3>口径与使用说明</h3><p>${esc(r.note)}</p></div>`:''}${q.answer_origin==='recap'&&q.current_answer===r.reference_answer?'':`<details><summary>查看表格参考回答</summary>${markdown(r.reference_answer)}</details>`}</div>`).join('')}</section>`;}

function collectionPage(s){document.title=s.name+' · 我的产品之路';root.innerHTML=crumbs(s)+`<header class="page-title"><h1>${esc(s.name)}</h1><p>${s.questions.length} 道题，${s.categories.length} 个主题${s.id==='general'?' · 一题一答与面试复盘':''}</p></header><section class="topic-list" aria-label="主题分类">${s.categories.map(c=>{const q=s.questions.find(q=>q.category_id===c.id);return `<a class="topic" href="${link(s,q)}"><strong>${esc(c.name)}</strong><small>${c.total} 题 ↗</small></a>`;}).join('')}</section>${reviewIndex(s)}${s.notes?`<details class="questions-index"><summary>已确认口径与原题号对照</summary><div class="answer">${markdown(s.notes)}</div></details>`:''}<p class="source-note">${s.id==='general'?'内容整理自一题一答合并版与四份面试复盘。既有主回答保留已确认口径；表格参考稿按来源单独展示。':'内容与参考回答整理自原面试训练站。'}</p>`;}
function reader(s,q){const c=s.categories.find(c=>c.id===q.category_id),items=s.questions.filter(i=>i.category_id===q.category_id),idx=items.findIndex(i=>i.id===q.id);document.title=q.question_text+' · 我的产品之路';root.innerHTML=crumbs(s,q)+`<div class="reader-layout"><aside class="rail" aria-label="主题目录"><p class="rail-title">${esc(s.name)} / ${s.categories.length} 个主题</p>${s.categories.map(cat=>`<a class="${cat.id===c.id?'selected':''}" ${cat.id===c.id?'aria-current="true"':''} href="${link(s,s.questions.find(i=>i.category_id===cat.id))}">${esc(cat.name)} <small>(${cat.total})</small></a>`).join('')}<a href="${link(s)}">查看全部主题</a></aside><article class="reader"><select class="mobile-topics" id="topic-picker" aria-label="选择主题">${s.categories.map(cat=>`<option value="${esc(s.questions.find(i=>i.category_id===cat.id).id)}" ${cat.id===c.id?'selected':''}>${esc(cat.name)} (${cat.total} 题)</option>`).join('')}</select><label class="rail-title" for="question-picker">${esc(c.name)}</label><select class="question-picker" id="question-picker">${items.map(i=>`<option value="${esc(i.id)}" ${i.id===q.id?'selected':''}>${String(i.number).padStart(2,'0')}. ${esc(i.question_text)}</option>`).join('')}</select><div class="question-meta"><span>题目 ${String(q.number).padStart(2,'0')}</span><span>本主题 ${idx+1} / ${items.length}</span>${q.reviews?.length?`<span>${q.reviews.length} 条复盘</span>`:''}</div><h1 class="question-title">${esc(q.question_text)}</h1><div class="hint"><p>先用自己的话回答，再展开参考答案。</p></div><div class="toolbar"><button id="previous" ${idx===0?'disabled':''}>上一题</button><button id="reveal" class="primary" aria-expanded="false" aria-controls="answer-body">展开参考回答</button><button id="next" ${idx===items.length-1?'disabled':''}>下一题</button></div><section class="answer" id="answer-body" hidden>${c.thinking_text?`<div class="strategy"><h3>本类通用回答框架</h3><p>${esc(c.thinking_text)}</p></div>`:''}${q.thinking_text?`<div class="strategy"><h3>面试官在听什么</h3><p>${esc(q.thinking_text)}</p></div>`:''}${q.flow_diagram?`<h2>${esc(q.flow_diagram.title)}</h2><div class="flow">${q.flow_diagram.nodes.map((n,i)=>`<div><strong>${i+1}. ${esc(n.label)}</strong><small>${esc(n.note)}</small></div>`).join('')}</div>`:''}<h2>${q.answer_origin==='recap'?'表格参考回答':'参考回答'}</h2>${q.answer_origin==='recap'?'<p class="review-source">以下为复盘材料中的参考稿，具体经历、指标与岗位语境使用前需核实。</p>':''}${markdown(q.current_answer)}${reviewPanels(q)}</section>${q.source_text?`<p class="source-note">${esc(q.source_text)}</p>`:''}<details class="questions-index"><summary>本主题全部题目（${items.length}）</summary>${items.map(i=>`<a href="${link(s,i)}" ${i.id===q.id?'aria-current="page"':''}>${String(i.number).padStart(2,'0')}. ${esc(i.question_text)}</a>`).join('')}</details></article></div>`;
for(const id of ['question-picker','topic-picker'])document.getElementById(id).onchange=e=>location.hash=link(s,{id:e.target.value});
document.getElementById('previous').onclick=()=>{if(idx>0)location.hash=link(s,items[idx-1]);};document.getElementById('next').onclick=()=>{if(idx<items.length-1)location.hash=link(s,items[idx+1]);};document.getElementById('reveal').onclick=e=>{const a=document.getElementById('answer-body');a.hidden=!a.hidden;e.target.textContent=a.hidden?'展开参考回答':'收起参考回答';e.target.setAttribute('aria-expanded',String(!a.hidden));};}
async function render(){const hash=location.hash||'#/';const parts=hash.replace(/^#\/?/,'').split('/').filter(Boolean);document.getElementById('home-nav').classList.toggle('active',!parts.length);document.getElementById('interview-nav').classList.toggle('active',parts[0]==='interview');if(!parts.length){root.innerHTML=home;document.title='我的产品之路';return;}
if(parts[0]!=='interview'){notFound();return;}
try{if(!spaces.length){root.innerHTML='<div class="empty" role="status">正在读取面试笔记…</div>';loading??=fetch('/content.json?v=recaps-1').then(r=>{if(!r.ok)throw Error('load');return r.json();});spaces=await loading;}if((location.hash||'#/')!==hash)return;if(!parts[1]){document.title='面试项 · 我的产品之路';root.innerHTML=crumbs()+`<header class="page-title"><h1>面试项</h1><p>把项目经验讲清楚，把产品思考讲透彻。</p></header><section class="collections">${spaces.map(s=>`<a class="collection" href="${link(s)}"><h2>${esc(s.name)}</h2><p>${esc(s.description)}</p><small>${s.questions.length} 道题 / ${s.categories.length} 个主题<br>查看目录 ↗</small></a>`).join('')}</section><p class="source-note">通用面试训练收录 80 道题，包含四份表格的 31 条面试复盘。常见问题与 AIGC 多模态内容保留原站当前回答和思路。<br><a href="https://interview-drill-95.xiaoxiao-ladidol.chatgpt.site/" target="_blank" rel="noopener">打开原面试训练站</a></p>`;}else{const s=spaces.find(s=>s.id===parts[1]);if(!s){notFound();return;}if(!parts[2])collectionPage(s);else{const q=s.questions.find(q=>q.id===parts[2]);if(q)reader(s,q);else notFound();}}}catch{loading=null;root.innerHTML='<div class="empty" role="alert"><h1>笔记暂时没有加载成功</h1><p>请检查网络后重试。</p><button class="button" id="retry">重新加载</button></div>';document.getElementById('retry').onclick=render;}}
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);});render();

document.querySelector(".skip").onclick=e=>{e.preventDefault();root.focus();root.scrollIntoView();};
